@router.post('/chat', response_model=ChatResponse)
async def chat(req: ChatRequest):
    """发送消息（非流式），返回完整回复。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'reply': 'Agent 未初始化', 'session_id': req.session_id or ''}

    import time
    t0 = time.monotonic()
    session_id = req.session_id or str(uuid.uuid4())

    # 确保会话已创建
    _ensure_session(app, session_id)

    # 收集流式输出为完整回复
    full_reply = []
    for chunk in app.process_message_stream(
            req.message, sender=req.sender, session_id=session_id):
        full_reply.append(chunk)

    reply = ''.join(full_reply)
    elapsed = (time.monotonic() - t0) * 1000

    # 自动生成标题
    _maybe_generate_title(app, session_id, req.message)

    return ChatResponse(
        reply=reply,
        session_id=session_id,
        elapsed_ms=round(elapsed, 1),
    )


