def _ensure_session(app, session_id: str):
    """确保会话记录存在。"""
    if not app or not hasattr(app, 'db'):
        return
    existing = app.db.get_session(session_id)
    if not existing:
        app.db.create_session(session_id)


def _maybe_generate_title(app, session_id: str, user_message: str):
    """当会话消息数 <= 2 时，用 LLM 生成简短标题。"""
    if not app or not hasattr(app, 'db'):
        return
    try:
        session = app.db.get_session(session_id)
        if not session:
            return
        # 只在首条消息后生成标题（message_count <= 2 说明刚完成第一轮对话）
        if session.get('message_count', 0) > 2:
            return
        # 如果标题已经不是默认的，不覆盖
        if session.get('title', '') not in ('新会话', ''):
            return
        # 使用 LLM 生成简短标题
        title = _generate_title(app, user_message)
        if title:
            app.db.update_session_title(session_id, title)
    except Exception:
        logger.debug('自动生成标题失败', exc_info=True)


def _generate_title(app, message: str) -> str:
    """用 LLM 从首条消息生成简短标题（10 字以内）。"""
    try:
        from agent_runtime.core.llm_client import AuxiliaryClient
        aux = getattr(app, 'aux', None)
        if not aux:
            # 简单截断作为兜底
            return message[:10].rstrip() or '新会话'
        client = aux.get_client('title')
        if not client:
            return message[:10].rstrip() or '新会话'
        resp = client.chat([
            {'role': 'system',
             'content': '根据用户消息生成一个简短的会话标题，不超过10个字，只输出标题文本，不要加引号或其他符号。'},
            {'role': 'user', 'content': message},
        ], max_tokens=30)
        title = (resp.get('content') or '').strip()[:10]
        return title or message[:10].rstrip()
    except Exception:
        # 兜底：截断用户消息
        return message[:10].rstrip() or '新会话'


def _sse_event(data: dict | str) -> str:
    """构造 SSE 事件行。"""
    if isinstance(data, str):
        return f'data: {data}\n\n'
    return f'data: {json.dumps(data, ensure_ascii=False)}\n\n'
